  "skills": [
    {
      "name": "docodego",
      "description": "The docodego front door. Use when starting work without a clear phase, when the user seems lost or unsure what to do next, or when routing between lifecycle phases (finding, grounding, promoting, building, nurturing, leaving, harvest). Routes to the Arc family (product/portfolio scale) or the loop family (spec scale).",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:180b1f91e86e24afbe8a701e36b9ee59d5334ae24d5d06a677cb4d7e655cea12",
      "defaultFor": [
        "docs-only",
        "minimal",
        "platform-team",
        "product-team",
        "research"
      ]
    },
    {
      "name": "docodego-compose",
      "description": "Use when implementing from existing .docodego spec files. Verifies the ICS gate, enforces the mandatory read order, writes an ephemeral plan for human approval, then drives RED-GREEN-REFACTOR from assurance criteria with strict commit discipline.",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:250edc19579f239ab0f7288088602553654b37489f37e20b46c4471fe50fe9c2",
      "defaultFor": [
        "platform-team",
        "product-team"
      ]
    },
    {
      "name": "docodego-demonstrate",
      "description": "Use when delivering or preparing delivery — gating on validation instead of schedule, running acceptance and launch-readiness checks, and (in maintenance) re-demonstrating that the system still does what its specs say. The delivery unit is the specification, all or nothing.",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:d942264289774a58772f144f135cc294de3834559e66c16b07d0c2279879ff80",
      "defaultFor": [
        "platform-team",
        "product-team"
      ]
    },
    {
      "name": "docodego-document",
      "description": "Use when authoring or revising specs for features, improvements, bugfixes, or refactors. Guides the multi-file spec (spec.md, assurance.md, deliverables.md), scores spec.md with the ICS scorer, iterates to the gate, then runs adversarial grilling.",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:2b1d4ce088971092b8c4edfa6d3dadc57cd33bad284dd4a19543c826f19cdc65",
      "defaultFor": [
        "docs-only",
        "platform-team",
        "product-team"
      ]
    },
    {
      "name": "docodego-finding",
      "description": "Use when someone doesn't know what to build, feels lost or restless about direction, keeps returning to a theme, or wants to capture a noticing before it evaporates. Guardian of thought provenance — produces finding records, never evaluations.",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:065686cabef656f7254a8615a49d008fa5137ae50a85d530a5f84b5eb8072f9c",
      "defaultFor": [
        "docs-only",
        "platform-team",
        "research"
      ]
    },
    {
      "name": "docodego-govern",
      "description": "Use for governance work — adversarial spec grilling, post-implementation validation, drift checks, the intent review, convention promotion, and measurement (AAR/GTR/SDL/DDL). Governance is an overlay across all phases, not a phase at the end.",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:d0c4b12e2f77ce1964172c871afbcd4ecc8435d1682dfe218a440dec64a0273a",
      "defaultFor": [
        "platform-team",
        "product-team"
      ]
    },
    {
      "name": "docodego-grounding",
      "description": "Use when deciding whether to commit to an idea — \"is this worth doing?\", \"should I build this?\". Facilitates the 36-question grounding walk in strict order, places the idea on the plane (a picture, never a score), and offers redesign moves before any kill.",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:c11f3be9a3fd71f5cf8db6d70529b33f2019327e240fb5af88602095146ee19c",
      "defaultFor": [
        "docs-only",
        "platform-team",
        "research"
      ]
    },
    {
      "name": "docodego-loop",
      "description": "The standing DoCoDeGo workflow. Use for any non-trivial engineering task — it enforces the DO→CO→DE→GO loop by default, refuses specless generation, and routes to docodego-document (author), docodego-compose (implement), docodego-demonstrate (deliver), docodego-govern (oversee).",
      "version": "1.0.0",
      "source": "bundled",
      "integrity": "sha256:48319003b5c1e6faae9e07523e81e5ce293a0cd98d720e96031a79b3679c091b",
      "defaultFor": [
        "platform-team",
        "product-team"
      ]
    }
  ],
